actions.script:
String bare = sourceHostName.startsWith('www.') ?
    sourceHostName.substring(4) : sourceHostName
String label = bare.contains('.') ? bare.substring(0, bare.indexOf('.')) : bare
String raw = ec.web?.getHostName(true)
if (!label || !raw) { context.hostName = ''; return }

String port = raw.contains(':') ? raw.substring(raw.indexOf(':')) : ''
String host = raw.contains(':') ? raw.substring(0, raw.indexOf(':')) : raw
// the default http/https ports are never part of a host name
if (port == ':80' || port == ':443') port = ''
if (host == '10.0.2.2' || host == '127.0.0.1') host = 'localhost'
// two or more dots: drop the first label, admin.growerp.org -> growerp.org
if (host.indexOf('.', host.indexOf('.') + 1) != -1) {
    host = host.substring(host.indexOf('.') + 1)
}
context.hostName = "${label}.${host}${port}"

def names = []
String sourceHost = null
try {
    sourceHost = new URL(sourceUrl).host
} catch (Exception e) {
    ec.message.addError("Cannot read the host name from ${sourceUrl}: ${e.message}")
}
if (hostNames) {
    names = hostNames.split(',').collect { it.trim() }.findAll { it }
} else if (sourceHost) {
    names.add(sourceHost)
    names.add(sourceHost.startsWith('www.') ? sourceHost.substring(4) : "www.${sourceHost}")
}
context.sourceHost = sourceHost
context.hostNameList = names.unique()

String base = (companyName as String).toUpperCase().replaceAll(/[^A-Z0-9]/, '')
if (base.length() > 12) base = base.substring(0, 12)
if (!base) base = 'SITE'
String candidate = base
int suffix = 2
while (true) {
    def wikiSpace = ec.entity.find("moqui.resource.wiki.WikiSpace")
        .condition("wikiSpaceId", "${candidate}_WS").disableAuthz().one()
    def root = ec.entity.find("moqui.resource.DbResource")
        .condition("resourceId", "${candidate}_ROOT").disableAuthz().one()
    def used = ec.entity.find("growerp.website.WebsiteConversion")
        .condition("siteId", candidate).disableAuthz().one()
    if (!wikiSpace && !root && !used) break
    candidate = "${base}${suffix++}"
    if (suffix > 50) break
}
context.siteId = candidate

def conversion = null
for (int attempt = 0; attempt < 10 && conversion == null; attempt++) {
    conversion = ec.entity.find("growerp.website.WebsiteConversion")
        .condition("conversionId", conversionId).useCache(false).disableAuthz().one()
    if (conversion == null) Thread.sleep(500)
}
context.conversion = conversion

def failed = { String message -> ec.logger.error("process#WebsiteConversion ${conversionId} failed: ${message}") ec.message.clearErrors() ec.service.sync() .name('growerp.100.WebsiteGeneratorServices100.update#WebsiteConversionStatus') .parameters([conversionId: conversionId, status: 'FAILED', statusMessage: 'Failed', errorMessage: message.take(4000), completedDate: ec.user.nowTimestamp]) .call() } def progress = { String status, String message -> ec.service.sync() .name('growerp.100.WebsiteGeneratorServices100.update#WebsiteConversionStatus') .parameters([conversionId: conversionId, status: status, statusMessage: message]) .call() }
// the api key of the owner that started the conversion def settings = ec.entity.find("growerp.general.SystemSettings") .condition("ownerPartyId", conversion.ownerPartyId).disableAuthz().one() String apiKey = settings?.geminiApiKey ?: ec.user.getPreference("GEMINI_API_KEY") ?: System.getenv("GEMINI_API_KEY") ?: System.getenv("GOOGLE_API_KEY")
try { // ---- scrape ------------------------------------------------------------- progress('SCRAPING', "Reading ${conversion.sourceUrl}") def scraped = ec.service.sync().name('growerp.100.WebsiteGeneratorServices100.scrape#WebsiteContent') .parameters([sourceUrl: conversion.sourceUrl, maxPages: conversion.maxPages]) .call() if (ec.message.hasError()) throw new Exception(ec.message.getErrorsString()) def siteData = scraped?.siteData if (!siteData || !siteData.pages) throw new Exception("No readable pages found on ${conversion.sourceUrl}")
// ---- generate ----------------------------------------------------------- progress('GENERATING', "Writing ${siteData.pages.size()} pages with AI") def generated = ec.service.sync().name('growerp.100.WebsiteGeneratorServices100.generate#WebsiteContent') .parameters([siteData: siteData, siteId: conversion.siteId, companyName: conversion.companyName, adminEmail: conversion.adminEmail, adminFirstName: conversion.adminFirstName, adminLastName: conversion.adminLastName, currencyId: conversion.currencyId, fiscalYearStartMonth: conversion.fiscalYearStartMonth, applicationId: conversion.applicationId, hostNames: (conversion.hostNames ?: '').split(',').collect { it.trim() }.findAll { it }, apiKey: apiKey, ownerPartyId: conversion.ownerPartyId]) .call() if (ec.message.hasError()) throw new Exception(ec.message.getErrorsString()) if (!generated?.xmlText) throw new Exception("The AI returned no website content") ec.service.sync() .name('growerp.100.WebsiteGeneratorServices100.update#WebsiteConversionStatus') .parameters([conversionId: conversionId, pageCount: generated.pageCount, imageCount: generated.imageCount]) .call()
// ---- install ------------------------------------------------------------ progress('IMPORTING', "Creating the owner and installing ${generated.pageCount} pages") def imported = ec.service.sync().name('growerp.100.ImportExportServices100.import#WebsiteOwner') .parameters([xmlText: generated.xmlText, siteId: conversion.siteId]) .call() if (ec.message.hasError()) throw new Exception(ec.message.getErrorsString())
ec.service.sync() .name('growerp.100.WebsiteGeneratorServices100.update#WebsiteConversionStatus') .parameters([conversionId: conversionId, status: 'COMPLETED', statusMessage: "Website ready on ${conversion.hostNames}", createdOwnerPartyId: imported.ownerPartyId, createdCompanyPartyId: imported.companyPartyId, productStoreId: imported.productStoreId, generatedPassword: imported.password, completedDate: ec.user.nowTimestamp]) .call() ec.logger.info("process#WebsiteConversion ${conversionId} completed, store ${imported.productStoreId}")
if (notifyUserId) { ec.makeNotificationMessage().topic('websiteConversion') .userId(notifyUserId as String).title('Website ready') .message([conversionId: conversionId, status: 'COMPLETED', message: "Website for ${conversion.companyName} is ready"]).send() } } catch (Exception e) { failed(e.message ?: e.toString()) if (notifyUserId) { ec.makeNotificationMessage().topic('websiteConversion') .userId(notifyUserId as String).title('Website conversion failed') .message([conversionId: conversionId, status: 'FAILED', message: "Conversion of ${conversion.sourceUrl} failed"]).send() } }

def matcher = (xmlText =~ /filename="([A-Za-z0-9]+)_ROOT"/)
context.siteId = matcher.find() ? matcher.group(1) : null
def specMatcher = (xmlText =~ /"companyName"\s*:\s*"([^"]*)"/)
context.fileCompanyName = specMatcher.find() ? specMatcher.group(1) : null
def emailMatcher = (xmlText =~ /"adminEmail"\s*:\s*"([^"]*)"/)
context.fileAdminEmail = emailMatcher.find() ? emailMatcher.group(1) : null
